"""Generate live/worker/src/cities.js from web/data/cities.json (stdlib only)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "web" / "data" / "cities.json"
OUT = ROOT / "live" / "worker" / "src" / "cities.js"


def main():
    cities = json.loads(SRC.read_text(encoding="utf-8"))
    lines = [
        "// generated by tools/gen_live_cities.py - do not edit by hand",
        "// Source: web/data/cities.json (id, core municipality INE code, name).",
        "export const CITIES = [",
    ]
    for c in cities:
        ine = str(c["core"]).zfill(5)
        lines.append(
            "  { id: %s, ine: %s, name: %s },"
            % (json.dumps(c["id"]), json.dumps(ine), json.dumps(c["name"], ensure_ascii=False))
        )
    lines.append("];")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote %d cities to %s" % (len(cities), OUT.relative_to(ROOT)))


if __name__ == "__main__":
    main()
